CREATE OR REPLACE FUNCTION public.icash_consume_automation(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.icash_automation_tickets;
begin
 update public.icash_automation_tickets set state='consumed' where token=p_token and state='issued' and expires_at>now() returning * into t;
 if not found then return null;end if;
 return jsonb_build_object('id',t.id,'accountId',t.account_id,'kind',t.kind,'screeningId',t.screening_id,'liveCallId',t.live_call_id,'signingId',t.signing_id,'voiceJobId',t.voice_job_id,'fulfillmentJobId',t.fulfillment_job_id,'titleTaskId',t.title_task_id,'textAiJobId',t.text_ai_job_id,'marketResearchJobId',t.market_research_job_id,'openerMessageId',t.opener_message_id);
end $function$

CREATE OR REPLACE FUNCTION public.icash_next_before_owner_question()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare recovered jsonb;
begin
 recovered:=public.icash_recover_unstarted_seller_opener();
 if recovered->>'token' is not null then return recovered;end if;
 return public.icash_next_outreach_channel();
end $function$

CREATE OR REPLACE FUNCTION public.icash_next_before_prospecting_budget()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j public.icash_title_tasks;t public.icash_automation_tickets;
begin
 perform pg_advisory_xact_lock(726341927);
 if exists(select 1 from public.icash_title_followup_settings where id=1 and enabled)
 and not exists(select 1 from public.icash_automation_tickets where kind='title_followup' and created_at>now()-interval '1 minute') then
  select f.* into j from public.icash_title_tasks f join public.icash_accounts a on a.id=f.account_id and not a.bot_paused
  join public.icash_deal_files d on d.id=f.deal_id and d.account_id=f.account_id and d.stage in ('under_contract','buyer_selected','title_open','closing')
  where f.kind='document_update' and f.state='scheduled' and f.email_retry_at<=now()
  and (f.email_state='waiting' or (f.email_state='issued' and f.updated_at<now()-interval '15 minutes'))
  order by f.email_retry_at,f.created_at for update of f skip locked limit 1;
  if found then
   update public.icash_title_tasks set email_state='issued',updated_at=now() where id=j.id;
   insert into public.icash_automation_tickets(account_id,kind,title_task_id) values(j.account_id,'title_followup',j.id) returning * into t;
   return jsonb_build_object('token',t.token);
  end if;
 end if;
 return public.icash_next_before_closing_gaps();
end $function$

CREATE OR REPLACE FUNCTION public.icash_next_before_unstarted_sms_recovery()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.icash_text_threads;m uuid;ticket public.icash_automation_tickets;
begin
 perform pg_advisory_xact_lock(726341927);
 if exists(select 1 from public.icash_operating_budget where id=1 and enabled) and not exists(select 1 from public.icash_automation_tickets where kind='seller_opener' and created_at>now()-interval '1 second') then
 with candidates as materialized (
 select th.id,th.account_id from public.icash_text_threads th join public.icash_accounts a on a.id=th.account_id and not a.bot_paused join public.icash_wallets w on w.account_id=a.id and w.balance_cents>w.reserved_cents join public.icash_deal_files d on d.id=th.deal_id and d.account_id=th.account_id and d.stage='draft' and coalesce(d.terms->>'practice','false')<>'true' join public.icash_screening_jobs sc on sc.id=d.screening_id and sc.account_id=d.account_id and sc.state='complete' and sc.result->'financialCheck'->>'status'='eligible' and sc.completed_at between now()-interval '24 hours' and now() join public.icash_timezone_names tz on tz.name=th.timezone
 where not exists(select 1 from public.icash_property_controls pc where pc.account_id=th.account_id and pc.property_id=sc.snapshot->>'propertyId' and pc.manual) and th.party='seller' and not th.paused and th.ai_mode='auto' and not exists(select 1 from public.icash_text_suppressions s where s.phone=th.recipient)
 and (not exists(select 1 from public.icash_text_messages where thread_id=th.id) or exists(select 1 from public.icash_sms_inbound_invitations i join public.icash_text_messages msg on msg.id=i.message_id and msg.state='ready' where i.thread_id=th.id and i.expires_at>now() and not exists(select 1 from public.icash_automation_tickets old where old.opener_message_id=msg.id)))
 )
 select ordered.* into t from (select th.* from candidates candidate join public.icash_text_threads th on th.id=candidate.id and th.account_id=candidate.account_id join public.icash_accounts a on a.id=th.account_id and not a.bot_paused join public.icash_wallets w on w.account_id=a.id and w.balance_cents>w.reserved_cents join public.icash_deal_files d on d.id=th.deal_id and d.account_id=th.account_id and d.stage='draft' and coalesce(d.terms->>'practice','false')<>'true' join public.icash_screening_jobs sc on sc.id=d.screening_id and sc.account_id=d.account_id and sc.state='complete' and sc.result->'financialCheck'->>'status'='eligible' and sc.completed_at between now()-interval '24 hours' and now() join public.icash_timezone_names tz on tz.name=th.timezone
 where public.icash_outreach_sms_current(candidate.account_id) and not exists(select 1 from public.icash_property_controls pc where pc.account_id=th.account_id and pc.property_id=sc.snapshot->>'propertyId' and pc.manual) and th.party='seller' and not th.paused and th.ai_mode='auto' and public.icash_sms_thread_dispatch_until(candidate.account_id,candidate.id)>now() and public.icash_sms_outreach_window_current(candidate.account_id,candidate.id) and not exists(select 1 from public.icash_text_suppressions s where s.phone=th.recipient)
 and (not exists(select 1 from public.icash_text_messages where thread_id=th.id) or exists(select 1 from public.icash_sms_inbound_invitations i join public.icash_text_messages msg on msg.id=i.message_id and msg.state='ready' where i.thread_id=th.id and i.expires_at>now() and not exists(select 1 from public.icash_automation_tickets old where old.opener_message_id=msg.id))) order by th.id for update of th skip locked offset 0) ordered
 where public.icash_seller_opener_candidate_body(ordered.account_id,ordered.id) is not null
 or exists(select 1 from public.icash_sms_inbound_invitations i
  join public.icash_text_messages msg on msg.id=i.message_id and msg.thread_id=ordered.id and msg.account_id=ordered.account_id and msg.state='ready'
  where i.thread_id=ordered.id and i.expires_at>now()
   and not exists(select 1 from public.icash_automation_tickets old where old.opener_message_id=msg.id))
 limit 1;
 if found then
  select i.message_id into m from public.icash_sms_inbound_invitations i join public.icash_text_messages msg on msg.id=i.message_id and msg.state='ready' where i.thread_id=t.id and i.expires_at>now();
  if m is null then m:=public.icash_queue_seller_opener(t.account_id,t.id);end if;
  if m is not null then insert into public.icash_automation_tickets(account_id,kind,opener_message_id) values(t.account_id,'seller_opener',m) returning * into ticket;return jsonb_build_object('token',ticket.token);end if;
 end if;end if;
 return public.icash_next_before_sms_inbound_campaign();
end $function$

CREATE OR REPLACE FUNCTION public.icash_resume_prospecting_ticket()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.icash_automation_tickets;op text;
begin
 perform 1 from public.icash_operating_budget where id=1 and enabled for update;
 if not found then return null;end if;
 for t in
  with waiting_accounts as materialized (
   select distinct account_id from public.icash_automation_tickets
   where state='held' and outcome='prospecting_budget_held' and expires_at<=now()
  ), allowances as materialized (
   select a.id,public.icash_prospecting_available(a.id) available
   from public.icash_accounts a join waiting_accounts w on w.account_id=a.id
   where not a.bot_paused and public.icash_membership_work_allowed(a.id)
  ), outreach_priority as materialized (
   select a.*,case when exists(
    select 1 from public.icash_automation_tickets pending where pending.account_id=a.id
     and pending.state='held' and pending.outcome='prospecting_budget_held' and pending.expires_at<=now()
     and pending.kind in ('contacts','discovery') and a.available>=pending.prospecting_quote_cents
   ) then public.icash_research_waiting_on_outreach(a.id) else false end waiting_for_outreach
   from allowances a
  )
  select x.* from public.icash_automation_tickets x join outreach_priority a on a.id=x.account_id
  where x.state='held' and x.outcome='prospecting_budget_held' and x.expires_at<=now()
  and a.available>=x.prospecting_quote_cents
  and (x.kind<>'voice_dispatch' or exists(
   select 1 from public.icash_voice_jobs v
   join public.icash_voice_contact_targets current_target
    on current_target.id=coalesce(v.permission_id,v.operational_contact_id) and current_target.account_id=v.account_id
   where v.id=x.voice_job_id and v.account_id=x.account_id
    and ((v.permission_id is not null and v.operational_contact_id is null and current_target.eligibility_source='operator_record')
     or (v.permission_id is null and v.operational_contact_id is not null and current_target.eligibility_source='operational_checks_only'))
    and current_target.revoked_at is null and current_target.permission_until>now()
  ))
  and (x.kind not in ('contacts','discovery') or (public.icash_dealmachine_capacity_available() and not a.waiting_for_outreach))
  order by x.created_at limit 20 for update of x skip locked loop
  op:=null;
  if t.kind='contacts' then op:='owners:'||t.account_id||':'||t.screening_id;
  elsif t.kind='voice_dispatch' then
   op:='voice:'||t.voice_job_id;
   if not exists(select 1 from public.icash_voice_jobs where id=t.voice_job_id and account_id=t.account_id and state='held' and outcome='prospecting_budget_held' and operation_key is null and conversation_id is null and provider_call_sid is null) then continue;end if;
  elsif t.kind in ('seller_opener','seller_recovery') then
   op:='text:'||t.opener_message_id;
   if not exists(select 1 from public.icash_text_messages where id=t.opener_message_id and account_id=t.account_id and state='ready' and provider_id is null and last_delivery_at is null) then continue;end if;
  elsif t.kind='discovery' then
   -- A discovery page can move independently. Its scheduler handles the current
   -- revision; do not replay a stale page capability.
   update public.icash_automation_tickets set outcome='prospecting_budget_released' where id=t.id;
   perform public.icash_wake_funded_outreach(t.account_id);continue;
  end if;
  if op is null or exists(select 1 from public.icash_operation_spend where operation_key=op) or exists(select 1 from public.icash_live_conversations where operation_key=op) then continue;end if;
  if exists(select 1 from public.icash_automation_tickets x where x.id<>t.id and x.account_id=t.account_id and ((x.state='issued' and x.expires_at>now()) or (x.state='consumed' and x.created_at>now()-interval '5 minutes'))) then continue;end if;
  if t.kind='voice_dispatch' then update public.icash_voice_jobs set state='issued',outcome=null,updated_at=now() where id=t.voice_job_id;end if;
  update public.icash_automation_tickets set token=gen_random_uuid()::text||gen_random_uuid()::text,state='issued',outcome=null,completed_at=null,created_at=now(),expires_at=now()+interval '2 minutes' where id=t.id returning * into t;
  return jsonb_build_object('token',t.token);
 end loop;
 return null;
end $function$

CREATE OR REPLACE FUNCTION public.icash_voice_outreach_context(p_account uuid, p_job uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare j public.icash_voice_jobs;p public.icash_voice_contact_targets;basis text;zone text;active boolean;stamp timestamptz:=clock_timestamp();
begin
 select * into j from public.icash_voice_jobs where id=p_job and account_id=p_account;
 if not found then return null;end if;
 select * into p from public.icash_voice_contact_targets
  where id=coalesce(j.permission_id,j.operational_contact_id) and account_id=p_account and party='seller';
 if not found then return null;end if;
 if j.operational_contact_id is not null then
  select timezone_basis into basis from public.icash_operational_contacts
   where id=j.operational_contact_id and account_id=p_account and channel='voice';
  if not found then return null;end if;
 end if;
 zone:=public.icash_outreach_timezone(p.timezone,basis);
 if zone is null then return null;end if;
 active:=public.icash_outreach_active_conversation(p_account,p.screening_id,p.phone,stamp)
  -- Preserve the dedicated, currently permitted contract-cancellation workflow.
  -- A job flag alone is not enough: its existing admission verifies the notice,
  -- agreement, property, recipient, account controls and contact evidence.
  or (j.cancellation_notice_id is not null and public.icash_cancellation_voice_current(p_account,'voice:'||j.id))
  or exists(select 1 from public.icash_live_callbacks cb
   join public.icash_live_conversations call on call.id=cb.conversation_id and call.account_id=cb.account_id
    and call.screening_id=cb.screening_id and call.contact_key=p.contact_key and call.party='seller' and call.state='complete'
   where cb.id=j.callback_id and cb.account_id=p_account and cb.screening_id=p.screening_id
    and cb.state='pending_dispatch_review' and cb.due_at between stamp-interval '15 minutes' and stamp
    and call.completed_at<=stamp and public.icash_call_has_seller_response(call.result)
    and case when pg_catalog.pg_input_is_valid(call.result->>'callbackDueAt','timestamp with time zone')
     then (call.result->>'callbackDueAt')::timestamptz=cb.due_at else false end);
 return jsonb_build_object('timezone',zone,
  'startHour',9,'endHour',21,'activeConversation',coalesce(active,false),
  'policyVersion','outreach-hours-2026-10-19');
end $function$

CREATE OR REPLACE FUNCTION public.icash_voice_outreach_hours_current(p_account uuid, p_job uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare context jsonb;
begin
 context:=public.icash_voice_outreach_context(p_account,p_job);
 if context is null then return false;end if;
 return public.icash_outreach_window_open(context->>'timezone',null,clock_timestamp());
end $function$
